SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS migrations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,migration VARCHAR(255) NOT NULL UNIQUE,batch INT UNSIGNED NOT NULL,executed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(100) NOT NULL UNIQUE,setting_value TEXT NULL,setting_type VARCHAR(20) NOT NULL DEFAULT 'text',setting_group VARCHAR(30) NOT NULL DEFAULT 'general',is_public TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(setting_group),INDEX(is_public)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS brands (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,description TEXT NULL,logo VARCHAR(255) NULL,website_url VARCHAR(255) NULL,country VARCHAR(100) NULL,is_featured TINYINT(1) DEFAULT 0,is_active TINYINT(1) DEFAULT 1,sort_order INT DEFAULT 0,meta_title VARCHAR(180) NULL,meta_description VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,INDEX(name),INDEX(is_active),INDEX(is_featured),INDEX(sort_order),INDEX(deleted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS brand_aliases (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,brand_id BIGINT UNSIGNED NOT NULL,alias VARCHAR(160) NOT NULL,normalized_alias VARCHAR(160) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(brand_id,normalized_alias),INDEX(normalized_alias),FOREIGN KEY(brand_id) REFERENCES brands(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,parent_id BIGINT UNSIGNED NULL,name VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,description TEXT NULL,image VARCHAR(255) NULL,icon VARCHAR(80) NULL,category_type VARCHAR(30) DEFAULT 'otro',is_featured TINYINT(1) DEFAULT 0,is_active TINYINT(1) DEFAULT 1,sort_order INT DEFAULT 0,meta_title VARCHAR(180) NULL,meta_description VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,INDEX(parent_id),INDEX(category_type),INDEX(is_active),INDEX(deleted_at),FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS olfactory_families (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,description TEXT NULL,icon VARCHAR(80) NULL,is_active TINYINT(1) DEFAULT 1,sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS notes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,description TEXT NULL,image VARCHAR(255) NULL,note_group VARCHAR(30) DEFAULT 'otros',is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(note_group),INDEX(is_active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS perfumes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,brand_id BIGINT UNSIGNED NULL,category_id BIGINT UNSIGNED NULL,olfactory_family_id BIGINT UNSIGNED NULL,name VARCHAR(200) NOT NULL,slug VARCHAR(220) NOT NULL UNIQUE,subtitle VARCHAR(255) NULL,short_description TEXT NULL,full_description TEXT NULL,gender VARCHAR(20) DEFAULT 'no_aplica',concentration VARCHAR(30) DEFAULT 'otro',launch_year SMALLINT UNSIGNED NULL,perfumer VARCHAR(160) NULL,origin_country VARCHAR(100) NULL,main_image VARCHAR(255) NOT NULL DEFAULT 'assets/images/placeholders/perfume.svg',video_url VARCHAR(255) NULL,status VARCHAR(30) DEFAULT 'borrador',availability_status VARCHAR(30) DEFAULT 'pendiente',is_published TINYINT(1) DEFAULT 0,is_featured TINYINT(1) DEFAULT 0,is_new TINYINT(1) DEFAULT 0,is_bestseller TINYINT(1) DEFAULT 0,is_promotion TINYINT(1) DEFAULT 0,show_price TINYINT(1) DEFAULT 0,price_from DECIMAL(10,2) NULL,price_text VARCHAR(120) NULL,whatsapp_message VARCHAR(500) NULL,season VARCHAR(100) NULL,occasion VARCHAR(160) NULL,intensity VARCHAR(30) NULL,longevity VARCHAR(30) NULL,sillage VARCHAR(30) NULL,audience VARCHAR(160) NULL,sort_order INT DEFAULT 0,views_count INT UNSIGNED DEFAULT 0,meta_title VARCHAR(180) NULL,meta_description VARCHAR(255) NULL,canonical_url VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,INDEX(brand_id),INDEX(category_id),INDEX(olfactory_family_id),INDEX(name),INDEX(gender),INDEX(status),INDEX(availability_status),INDEX(is_published),INDEX(is_featured),INDEX(is_new),INDEX(is_bestseller),INDEX(is_promotion),INDEX(sort_order),INDEX(created_at),INDEX(deleted_at),FOREIGN KEY(brand_id) REFERENCES brands(id) ON DELETE SET NULL,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,FOREIGN KEY(olfactory_family_id) REFERENCES olfactory_families(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS perfume_categories (perfume_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NOT NULL,is_primary TINYINT(1) DEFAULT 0,sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(perfume_id,category_id),INDEX(category_id),FOREIGN KEY(perfume_id) REFERENCES perfumes(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS perfume_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,perfume_id BIGINT UNSIGNED NOT NULL,image_path VARCHAR(255) NOT NULL,thumbnail_path VARCHAR(255) NULL,alt_text VARCHAR(255) NULL,caption VARCHAR(255) NULL,sort_order INT DEFAULT 0,is_primary TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(perfume_id),FOREIGN KEY(perfume_id) REFERENCES perfumes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS perfume_notes (perfume_id BIGINT UNSIGNED NOT NULL,note_id BIGINT UNSIGNED NOT NULL,note_position VARCHAR(20) DEFAULT 'general',sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(perfume_id,note_id,note_position),FOREIGN KEY(perfume_id) REFERENCES perfumes(id) ON DELETE CASCADE,FOREIGN KEY(note_id) REFERENCES notes(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS perfume_presentations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,perfume_id BIGINT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,size_value DECIMAL(8,2) NULL,size_unit VARCHAR(20) NULL,sku VARCHAR(100) NULL,barcode VARCHAR(80) NULL,price DECIMAL(10,2) NULL,show_price TINYINT(1) DEFAULT 0,availability_status VARCHAR(30) DEFAULT 'pendiente',is_active TINYINT(1) DEFAULT 1,sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(perfume_id) REFERENCES perfumes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,description TEXT NULL,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS perfume_tags (perfume_id BIGINT UNSIGNED NOT NULL,tag_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(perfume_id,tag_id),FOREIGN KEY(perfume_id) REFERENCES perfumes(id) ON DELETE CASCADE,FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS perfume_aliases (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,perfume_id BIGINT UNSIGNED NOT NULL,alias VARCHAR(220) NOT NULL,normalized_alias VARCHAR(220) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(perfume_id,normalized_alias),INDEX(normalized_alias),FOREIGN KEY(perfume_id) REFERENCES perfumes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS promotions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,short_description TEXT NULL,full_description TEXT NULL,image VARCHAR(255) NULL,mobile_image VARCHAR(255) NULL,promotion_type VARCHAR(30) NULL,discount_text VARCHAR(120) NULL,starts_at DATETIME NULL,ends_at DATETIME NULL,is_active TINYINT(1) DEFAULT 0,is_featured TINYINT(1) DEFAULT 0,button_text VARCHAR(80) NULL,button_url VARCHAR(255) NULL,whatsapp_message VARCHAR(500) NULL,sort_order INT DEFAULT 0,meta_title VARCHAR(180) NULL,meta_description VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,INDEX(starts_at,ends_at),INDEX(is_active),INDEX(deleted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS promotion_perfumes (promotion_id BIGINT UNSIGNED NOT NULL,perfume_id BIGINT UNSIGNED NOT NULL,sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(promotion_id,perfume_id),FOREIGN KEY(promotion_id) REFERENCES promotions(id) ON DELETE CASCADE,FOREIGN KEY(perfume_id) REFERENCES perfumes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS banners (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,title VARCHAR(180) NULL,subtitle VARCHAR(255) NULL,description TEXT NULL,desktop_image VARCHAR(255) NULL,mobile_image VARCHAR(255) NULL,button_text VARCHAR(80) NULL,button_url VARCHAR(255) NULL,position VARCHAR(40) DEFAULT 'home_hero',text_alignment VARCHAR(20) DEFAULT 'left',overlay_opacity DECIMAL(3,2) DEFAULT .20,starts_at DATETIME NULL,ends_at DATETIME NULL,is_active TINYINT(1) DEFAULT 0,sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,INDEX(position),INDEX(starts_at,ends_at),INDEX(is_active),INDEX(deleted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS testimonials (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,author_name VARCHAR(120) NOT NULL,author_avatar VARCHAR(255) NULL,quote TEXT NOT NULL,rating TINYINT UNSIGNED NULL,is_verified TINYINT(1) NOT NULL DEFAULT 0,source VARCHAR(80) NULL,is_featured TINYINT(1) DEFAULT 0,is_active TINYINT(1) DEFAULT 0,sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,INDEX(is_active),INDEX(is_verified),INDEX(deleted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL UNIQUE,excerpt TEXT NULL,content LONGTEXT NULL,featured_image VARCHAR(255) NULL,status VARCHAR(30) DEFAULT 'borrador',is_published TINYINT(1) DEFAULT 0,published_at DATETIME NULL,meta_title VARCHAR(180) NULL,meta_description VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,INDEX(status),INDEX(is_published),INDEX(deleted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS faqs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,question VARCHAR(255) NOT NULL,answer TEXT NOT NULL,category VARCHAR(100) NULL,is_active TINYINT(1) DEFAULT 0,sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,INDEX(is_active),INDEX(deleted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS contact_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NULL,email VARCHAR(180) NULL,phone VARCHAR(40) NULL,subject VARCHAR(180) NULL,message TEXT NOT NULL,status VARCHAR(30) DEFAULT 'nuevo',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,INDEX(status),INDEX(created_at),INDEX(deleted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS store_hours (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,day_of_week TINYINT UNSIGNED NOT NULL,day_name VARCHAR(30) NOT NULL,is_closed TINYINT(1) DEFAULT 1,opens_at TIME NULL,closes_at TIME NULL,second_opens_at TIME NULL,second_closes_at TIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(day_of_week)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS social_links (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,platform VARCHAR(40) NOT NULL,label VARCHAR(80) NULL,url VARCHAR(255) NULL,icon VARCHAR(80) NULL,is_active TINYINT(1) DEFAULT 0,sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(platform)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,file_name VARCHAR(180) NOT NULL,path VARCHAR(255) NOT NULL,mime_type VARCHAR(100) NOT NULL,size_bytes BIGINT UNSIGNED DEFAULT 0,alt_text VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,INDEX(mime_type),INDEX(deleted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,action VARCHAR(80) NOT NULL,entity_type VARCHAR(80) NULL,entity_id BIGINT UNSIGNED NULL,details JSON NULL,ip_address VARCHAR(45) NULL,user_agent VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(action),INDEX(entity_type,entity_id),INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,identifier VARCHAR(120) NULL,identifier_hash CHAR(64) NULL,ip_address VARCHAR(45) NULL,ip_hash CHAR(64) NULL,attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NULL,was_successful TINYINT(1) DEFAULT 0,INDEX(identifier_hash),INDEX(ip_hash),INDEX(expires_at),INDEX(identifier),INDEX(attempted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
